package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class SupervisionFailureRebootTest {

    private static final String REBOOT_CAUSE_FILE = "target/supervisionFailureRebootCause";
    private static final String WATCHDOG_DEVICE = "target/supervisionFailureWatchdogDevice";
    private static final String EXPECTED_REBOOT_CAUSE = "watchdog-poll-failure: java.lang.IllegalStateException";
    private static final int PING_INTERVAL_MS = 20;
    private static final long REBOOT_WAIT_TIMEOUT_MS = 10000;
    private static final long OBSERVATION_TIME_MS = 300;

    private final SupervisionTestWatchdogServiceImpl svc = new SupervisionTestWatchdogServiceImpl();
    private String watchdogMode;

    @Test
    public void supervisionFailureRequestsRebootInDirectMode() throws Exception {
        givenWatchdogMode("direct");
        givenSupervisionFails();

        whenWatchdogServiceIsActivated();

        thenRebootIsRequested();
        thenRebootCauseIs(EXPECTED_REBOOT_CAUSE);
    }

    @Test
    public void supervisionFailureRequestsRebootInSystemdMode() throws Exception {
        givenWatchdogMode("systemd");
        givenSupervisionFails();

        whenWatchdogServiceIsActivated();

        thenRebootIsRequested();
        thenRebootCauseIs(EXPECTED_REBOOT_CAUSE);
    }

    @Test
    public void supervisionFailureRequestsRebootInFallbackMode() throws Exception {
        givenWatchdogMode("fallback");
        givenSupervisionFails();

        whenWatchdogServiceIsActivated();

        thenRebootIsRequested();
        thenRebootCauseIs(EXPECTED_REBOOT_CAUSE);
    }

    @Test
    public void supervisionFailureAfterHealthyTicksRequestsReboot() throws Exception {
        givenWatchdogMode("fallback");

        whenWatchdogServiceIsActivated();
        whenWatchdogIsObserved();
        whenSupervisionStartsFailing();

        thenRebootIsRequested();
        thenRebootCauseIs(EXPECTED_REBOOT_CAUSE);
    }

    @Test
    public void healthySupervisionDoesNotRequestReboot() throws Exception {
        givenWatchdogMode("fallback");

        whenWatchdogServiceIsActivated();
        whenWatchdogIsObserved();

        thenNoRebootIsRequested();
        thenNoRebootCauseIsWritten();
    }

    @Before
    public void deleteRebootCauseFileBefore() {
        new File(REBOOT_CAUSE_FILE).delete();
    }

    @After
    public void cleanup() {
        this.svc.deactivate();
        new File(REBOOT_CAUSE_FILE).delete();
    }

    private void givenWatchdogMode(final String mode) {
        this.watchdogMode = mode;
    }

    private void givenSupervisionFails() {
        this.svc.setSupervisionFailing(true);
    }

    private void whenWatchdogServiceIsActivated() {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", true);
        properties.put("watchdogMode", this.watchdogMode);
        properties.put("watchdogDevice", WATCHDOG_DEVICE);
        properties.put("pingInterval", PING_INTERVAL_MS);
        properties.put("rebootCauseFilePath", REBOOT_CAUSE_FILE);
        this.svc.activate(properties);
    }

    private void whenWatchdogIsObserved() throws InterruptedException {
        Thread.sleep(OBSERVATION_TIME_MS);
    }

    private void whenSupervisionStartsFailing() {
        this.svc.setSupervisionFailing(true);
    }

    private void thenRebootIsRequested() throws InterruptedException {
        assertTrue(this.svc.awaitRebootRequest(REBOOT_WAIT_TIMEOUT_MS));
    }

    private void thenNoRebootIsRequested() {
        assertEquals(0, this.svc.getRebootRequests());
    }

    private void thenRebootCauseIs(final String expectedCause) throws IOException {
        final List<String> lines = Files.readAllLines(new File(REBOOT_CAUSE_FILE).toPath());
        assertEquals(2, lines.size());
        assertEquals(expectedCause, lines.get(1));
    }

    private void thenNoRebootCauseIsWritten() {
        assertFalse(new File(REBOOT_CAUSE_FILE).exists());
    }
}
